mapper.select:
SELECT id, user_id, type, target_id, extra, created_at
FROM collections
WHERE user_id = #{userId}
  AND type = #{type}
ORDER BY created_at DESC

SELECT id, user_id, type, target_id, extra, created_at
FROM collections
WHERE user_id = #{userId}
  AND type = #{type}
  AND target_id = #{targetId}
LIMIT 1

mapper.delete:
DELETE FROM collections
WHERE id = #{id}
  AND user_id = #{userId}
